// The webhook path is static, so the icon name arrives in the query string.
// Map it onto params.name, which is what Pick Icon reads.
var q = $json.query || {};
return [{ json: { params: { name: String(q.name || "") } } }];

// The four CBS ServiceM8 add-on icons, 256x256 palette PNGs.
// Served by /webhook/cbs-addon-icons?name=<name>, referenced from each
// CBS add-on addon.jsonc. Artwork is byte-identical to the Embr set.
var ICONS = {"onsite":"","team":"","site-prep":"","survey":""};
var name = String((($json.params || {}).name) || "").toLowerCase().replace(/\.png$/, "");
var b64 = ICONS[name];
var served = name;
if (!b64) { served = "onsite"; b64 = ICONS[served]; }
return [{ json: { requested: name, served: served }, binary: { data: { data: b64, mimeType: "image/png", fileName: served + ".png", fileExtension: "png" } } }];

// Extra CBS add-on icons added after the original four. Pick Icon falls back to 'onsite' for unknown names;
// this swaps in the right artwork when the requested name is one of these.
var EXTRA = {"enquiry":""};
var it = $input.first();
var j = it.json || {};
if (EXTRA[j.requested]) {
  return [{ json: { requested: j.requested, served: j.requested }, binary: { data: { data: EXTRA[j.requested], mimeType: 'image/png', fileName: j.requested + '.png', fileExtension: 'png' } } }];
}
return [it];

